'use strict';

// Generic fixture harness for ONE portal adapter (portal-adapters T4).
//   node extension_portal_fixture_harness.js <portal-id>
// Loads extension/portals/<id>.js, runs extractCards over
// tests/fixtures/portals/<id>.html through the minimal DOM (minidom.js) and
// compares with <id>.expected.json:
//   { "cards": [{id,title,company,location,link}, ...],   // 3+ cards
//     "no_results_text": "the portal's own empty-results copy",
//     "urls": ["offer or search URLs on the portal host"] }
// Generated by scripts/new_portal.py's test files; exit 0 on success.

const fs = require('fs');
const path = require('path');
const { pathToFileURL } = require('url');
const { installDocument, uninstallDocument } = require('./minidom.js');

const failures = [];
function check(name, actual, expected) {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) failures.push(`${name}: expected ${e}, got ${a}`);
}

// Page extractors wait (setTimeout) before reading the DOM: run them at once.
globalThis.setTimeout = (fn) => setImmediate(fn);

const load = (rel) => import(pathToFileURL(path.resolve(__dirname, '..', '..', 'extension', rel)).href);

async function main() {
  const id = process.argv[2];
  if (!id || !/^[a-z][a-z0-9]*$/.test(id)) throw new Error('usage: harness <portal-id>');
  const dir = path.join(__dirname, 'portals');
  const html = fs.readFileSync(path.join(dir, `${id}.html`), 'utf8');
  const expected = JSON.parse(fs.readFileSync(path.join(dir, `${id}.expected.json`), 'utf8'));
  const { default: portal } = await load(`portals/${id}.js`);
  const { markersToSource } = await load('portals/registry.js');

  check('adapter id matches its file', portal.id, id);
  check('contract fields', [
    typeof portal.label, typeof portal.hostMatch, typeof portal.extractCards,
    Array.isArray(portal.noResultsMarkers), typeof portal.canonicalUrl,
    typeof portal.linkHost, typeof portal.buildSearchUrl,
  ], ['string', 'function', 'function', true, 'function', 'string', 'function']);
  check('extractCards is a named function', portal.extractCards.name.length > 0, true);

  if (!Array.isArray(expected.cards) || expected.cards.length < 3) {
    failures.push('expected.json needs 3+ cards taken from the saved page (RED until the fixture is filled in)');
  }

  installDocument(html);
  let cards;
  try {
    cards = await portal.extractCards();
  } finally {
    uninstallDocument();
  }
  check('cards extracted from the saved page', cards, expected.cards);

  const markers = markersToSource(portal.noResultsMarkers);
  check('no-results copy is recognised', Boolean(expected.no_results_text)
    && new RegExp(markers, 'i').test(expected.no_results_text), true);
  check('unrelated text is not a no-results marker', new RegExp(markers, 'i').test('Something went wrong'), false);

  for (const url of expected.urls || []) {
    check(`hostMatch accepts ${url}`, portal.hostMatch(url), true);
  }
  check('hostMatch rejects foreign hosts', portal.hostMatch('https://example.com/jobs'), false);

  const built = portal.buildSearchUrl({ keywords: 'ai engineer', location: 'Barcelona' });
  check('buildSearchUrl returns a portal URL', typeof built === 'string' && portal.hostMatch(built), true);
  // A portal whose search has no keyword parameter (Manfred) sets "ignores_keywords".
  if (!expected.ignores_keywords) {
    check('buildSearchUrl carries the keywords',
      decodeURIComponent(String(built)).replace(/\+/g, ' ').toLowerCase().includes('ai engineer'), true);
  }

  if (failures.length) {
    console.error(`FAIL (${id}): ${failures.length} assertion(s) failed:`);
    for (const f of failures) console.error(' - ' + f);
    process.exitCode = 1;
  } else {
    process.stdout.write(`OK: ${id} adapter assertions passed\n`);
  }
}

main().catch((e) => {
  console.error('harness crashed:', (e && e.stack) || e);
  process.exitCode = 1;
});
